// Original project illustrations, deliberately distinct from live deployment previews.
const grid='<pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M 24 0 L 0 0 0 24" fill="none" stroke="#b2c382" stroke-opacity=".09" stroke-width=".6"/></pattern><rect width="500" height="320" fill="url(#grid)"/>';
export function projectArt(kind='code',index=0) {
 const head='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 320" aria-hidden="true">';
 if(kind==='math'){
  let paths='';
  for(let j=-9;j<=9;j++){let d='';for(let i=0;i<=65;i++){const x=-2.3+i/65*4.6,y=j/9*2.3,z=Math.sin(Math.hypot(x,y)*2.1)*.9;const sx=250+(x-y)*44,sy=164+(x+y)*17-z*42;d+=`${i?'L':'M'}${sx.toFixed(1)} ${sy.toFixed(1)} `;}paths+=`<path d="${d}"/>`;}
  for(let j=-9;j<=9;j++){let d='';for(let i=0;i<=65;i++){const y=-2.3+i/65*4.6,x=j/9*2.3,z=Math.sin(Math.hypot(x,y)*2.1)*.9;const sx=250+(x-y)*44,sy=164+(x+y)*17-z*42;d+=`${i?'L':'M'}${sx.toFixed(1)} ${sy.toFixed(1)} `;}paths+=`<path d="${d}"/>`;}
  return head+'<rect width="500" height="320" fill="#1b241b"/>'+grid+`<g fill="none" stroke="#b8d483" stroke-width=".8" opacity=".8">${paths}</g><text x="35" y="268" fill="#a3b89c" font-size="11" font-family="monospace">z = sin(√(x² + y²))</text></svg>`;
 }
 if(kind==='canvas') return head+'<rect width="500" height="320" fill="#27251f"/>'+grid+'<g transform="rotate(-7 250 160)"><rect x="106" y="62" width="290" height="201" rx="6" fill="#dedacb"/><rect x="106" y="62" width="290" height="22" rx="6" fill="#c9c7b7"/><circle cx="121" cy="73" r="3" fill="#8c9277"/><circle cx="132" cy="73" r="3" fill="#8c9277"/><path d="M145 218H362M180 101V235" stroke="#999d89" stroke-width="1"/><path d="M143 173Q188 85 231 170T361 166" stroke="#768542" stroke-width="3" fill="none"/><text x="233" y="123" fill="#5c664a" font-family="Georgia" font-size="18" font-style="italic">a little infinity.</text><text x="249" y="241" fill="#93957d" font-size="10" font-family="monospace">∫ f(x) dx</text></g><path d="M383 239L431 122" stroke="#1a1c18" stroke-width="12" stroke-linecap="round"/><path d="M383 239l-2 15 8-12" fill="#9b9d7f"/></svg>';
 if(kind==='vision') return head+'<rect width="500" height="320" fill="#1c2627"/>'+grid+'<g stroke="#638f8a" fill="none" stroke-width="1"><rect x="155" y="52" width="189" height="221" stroke-dasharray="5 6"/><path d="M155 82V52h30m129 0h30v30m0 161v30h-30m-129 0h-30v-30" stroke="#98d7bb" stroke-width="2"/></g><g stroke="#b3d8b4" fill="none" stroke-width="2"><circle cx="249" cy="96" r="16"/><path d="M249 113v66m-41-48 41 11 40-13m-81 2-29 34-26-18m136-18 28 32 28-11m-96 29-24 43-13 28m37-71 26 41 12 31"/></g><g fill="#d5ef72"><circle cx="249" cy="142" r="4"/><circle cx="208" cy="131" r="4"/><circle cx="289" cy="129" r="4"/><circle cx="249" cy="179" r="4"/><circle cx="225" cy="222" r="4"/><circle cx="275" cy="220" r="4"/></g><text x="167" y="69" fill="#b3d8b4" font-family="monospace" font-size="9">POSE VISUALIZATION</text></svg>';
 if(kind==='watch') return head+'<rect width="500" height="320" fill="#2c241c"/><circle cx="250" cy="160" r="130" fill="none" stroke="#b0946022"/><rect x="218" y="-10" width="64" height="340" rx="20" fill="#3a3127"/><path d="M224 0v320m52-320v320" stroke="#715b3a"/><circle cx="250" cy="160" r="77" fill="#beaa7a"/><circle cx="250" cy="160" r="69" fill="#121511"/><circle cx="250" cy="160" r="61" fill="none" stroke="#7f775a" stroke-dasharray="1 14.8" stroke-width="5"/><path d="M250 119v41l30 19" fill="none" stroke="#d6cba6" stroke-width="3"/><circle cx="250" cy="160" r="4" fill="#d6cba6"/><text x="250" y="139" text-anchor="middle" fill="#bba77b" font-family="Georgia" font-size="11" letter-spacing="4">AUREL</text><rect x="326" y="148" width="7" height="22" rx="2" fill="#9e8556"/></svg>';
 if(kind==='counter') return head+'<rect width="500" height="320" fill="#242725"/>'+grid+'<path d="M90 320L193 30m220 290L308 30M250 320V30" stroke="#c3cabc1f" stroke-width="2" stroke-dasharray="14 14"/><g fill="#566252"><rect x="185" y="97" width="40" height="62" rx="8"/><rect x="278" y="183" width="46" height="72" rx="8"/><rect x="204" y="235" width="43" height="62" rx="8"/></g><g fill="none" stroke="#d5ef72" stroke-width="1"><rect x="177" y="88" width="56" height="79"/><rect x="270" y="174" width="62" height="90"/></g><path d="M84 186h338" stroke="#d5ef72" stroke-dasharray="5 4"/><g fill="#d5ef72" font-size="8" font-family="monospace"><text x="177" y="82">OBJECT 01</text><text x="270" y="169">OBJECT 02</text><text x="84" y="179">COUNTING LINE</text></g></svg>';
 const palettes=[['#202527','#8fbfc5'],['#24231f','#c9bf86'],['#242027','#c1a8cf']]; const [bg,fg]=palettes[index%3];
 return head+`<rect width="500" height="320" fill="${bg}"/>`+grid+`<rect x="89" y="62" width="322" height="204" rx="7" fill="#101611" stroke="${fg}" stroke-opacity=".25"/><path d="M89 88h322" stroke="${fg}" stroke-opacity=".2"/><g fill="${fg}" opacity=".55"><circle cx="103" cy="75" r="3"/><circle cx="114" cy="75" r="3"/><circle cx="125" cy="75" r="3"/></g><g font-family="monospace" font-size="13"><text x="111" y="121" fill="#7b8474">// ideas into interfaces</text><text x="111" y="151" fill="${fg}">const create = (idea) =&gt; {</text><text x="128" y="178" fill="#d7decf">return build(idea);</text><text x="111" y="205" fill="${fg}">};</text><text x="111" y="242" fill="#7b8474">▸ always learning_</text></g></svg>`;
}
